mapper.select:
select tenant_name, device_prod_category_name, create_time, sum(total_num) as total_num, sum(un_confirmed_num) as un_confirmed_num, sum(progress_confirmed_num) as progress_confirmed_num, sum(suspend_num) as suspend_num, sum(handler_num) as handler_num from medical_alarm_statistics
tenant = #{param.tenant}
and device_prod_category_code =#{param.deviceProdCategoryCode}
and create_time between #{param.period.begin} and #{param.period.end}
group by tenant,device_prod_category_code
